/**
 * main/terminal-keys.ts — physical key presses → terminal bytes, for the root terminal window.
 *
 * The window that shows a program running as ROOT takes no input from its renderer at all. Main
 * reads the keys from Electron's `before-input-event` — generated by the browser process from
 * real keyboard input, which renderer JavaScript cannot synthesise — and turns them into the
 * bytes an xterm-compatible terminal would send. So nothing that runs in a page (a compromised
 * renderer, a rendered file name, an extension) can type into a root program.
 *
 * Covers what a curses program uses: printable characters, Enter/Backspace/Tab/Escape, cursor
 * and editing keys (honouring the program's cursor-key mode, DECCKM), F1–F12, Ctrl+letter and
 * Alt (ESC-prefixed). Cmd (meta) combinations send nothing, so menu shortcuts stay the app's.
 */

export interface KeyInput {
  type: string;
  key: string;
  control: boolean;
  alt: boolean;
  shift: boolean;
  meta: boolean;
}

const NAMED: Record<string, string> = {
  Enter: "\r",
  Backspace: "\x7f",
  Tab: "\t",
  Escape: "\x1b",
  Insert: "\x1b[2~",
  Delete: "\x1b[3~",
  PageUp: "\x1b[5~",
  PageDown: "\x1b[6~",
  F1: "\x1bOP",
  F2: "\x1bOQ",
  F3: "\x1bOR",
  F4: "\x1bOS",
  F5: "\x1b[15~",
  F6: "\x1b[17~",
  F7: "\x1b[18~",
  F8: "\x1b[19~",
  F9: "\x1b[20~",
  F10: "\x1b[21~",
  F11: "\x1b[23~",
  F12: "\x1b[24~",
};

/** Cursor keys: the final byte; `CSI x` normally, `SS3 x` in application cursor-key mode. */
const CURSOR: Record<string, string> = {
  ArrowUp: "A",
  ArrowDown: "B",
  ArrowRight: "C",
  ArrowLeft: "D",
  Home: "H",
  End: "F",
};

/** Ctrl + one of these punctuation keys → its C0 control. */
const CTRL_PUNCT: Record<string, string> = {
  "[": "\x1b",
  "\\": "\x1c",
  "]": "\x1d",
  "^": "\x1e",
  _: "\x1f",
  "@": "\x00",
  " ": "\x00",
};

export function keyToTerminalBytes(
  input: KeyInput,
  opts: { appCursor?: boolean } = {},
): string | null {
  if (input.type !== "keyDown" || input.meta) return null;
  const { key } = input;

  const cursor = CURSOR[key];
  if (cursor) return `${opts.appCursor ? "\x1bO" : "\x1b["}${cursor}`;
  if (key === "Tab" && input.shift) return "\x1b[Z";
  const named = NAMED[key];
  if (named) return named;

  // a single character (one code point — "è", "å" — not a key name like "Shift")
  if ([...key].length !== 1) return null;

  if (input.control) {
    const lower = key.toLowerCase();
    if (lower >= "a" && lower <= "z") return String.fromCharCode(lower.charCodeAt(0) - 96);
    return CTRL_PUNCT[key] ?? null;
  }
  // Alt as meta (ESC prefix) for ASCII; on macOS Option already produced a character — send it
  if (input.alt && key.charCodeAt(0) < 0x80) return `\x1b${key}`;
  return key;
}

/**
 * Track the program's cursor-key mode (DECCKM, `ESC [ ? 1 h` / `l`) from its output, so the
 * arrows send what it asked for. `tail` carries a sequence split across two chunks.
 */
export function cursorKeysMode(
  state: { appCursor: boolean; tail: string },
  chunk: string,
): { appCursor: boolean; tail: string } {
  const text = state.tail + chunk;
  let appCursor = state.appCursor;
  for (const m of text.matchAll(/\x1b\[\?([\d;]+)([hl])/g)) {
    if ((m[1] ?? "").split(";").includes("1")) appCursor = m[2] === "h";
  }
  return { appCursor, tail: text.slice(-16) };
}
